document.addEventListener("DOMContentLoaded",()=>{const tabs=document.querySelectorAll(".section-propiedades .tab");const contents=document.querySelectorAll(".section-propiedades .tab-content");document.querySelector(".section-propiedades").addEventListener("click",(e)=>{const tab=e.target.closest(".tab");if(tab){tabs.forEach(t=>t.classList.remove("active"));contents.forEach(t=>t.classList.remove("active"));const content=document.querySelector('.section-propiedades .tab-content[data-content="'+tab.dataset.tab+'"]');content.classList.add("active");tab.classList.add("active")}})})